<?php
declare(strict_types=1);
namespace KodVadAll\Modules\Returns;
use PDO;
use RuntimeException;
use Throwable;

final class ReturnController
{
 private const LABELS=['requested'=>'Talep edildi','approved'=>'Onaylandı','rejected'=>'Reddedildi','received'=>'Ürün teslim alındı','refunded'=>'İade ödendi','closed'=>'Kapatıldı'];
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('returns.view');$action=(string)($_GET['action']??'list');$id=max(0,(int)($_GET['id']??0));$errors=[];
  if($_SERVER['REQUEST_METHOD']==='POST'){
   kd_csrf_check();kd_require_permission('returns.manage');
   try{
    $form=(string)($_POST['form_action']??'');
    if($form==='create'){
     $orderId=(int)($_POST['order_id']??0);$reason=trim((string)($_POST['reason']??''));$q=$db->prepare("SELECT * FROM orders WHERE id=? AND status IN ('shipped','completed')");$q->execute([$orderId]);$order=$q->fetch();if(!$order)throw new RuntimeException('İade için kargolanmış veya tamamlanmış sipariş seçin.');if($reason==='')throw new RuntimeException('İade nedeni zorunludur.');
     $qtys=is_array($_POST['quantity']??null)?$_POST['quantity']:[];$q=$db->prepare('SELECT * FROM order_items WHERE order_id=? AND product_id IS NOT NULL ORDER BY id');$q->execute([$orderId]);$orderItems=$q->fetchAll();$items=[];$total=0;
     foreach($orderItems as $it){$qty=(float)($qtys[$it['id']]??0);if($qty<=0)continue;$already=$db->prepare("SELECT COALESCE(SUM(ri.quantity),0) FROM sales_return_items ri JOIN sales_returns r ON r.id=ri.return_id WHERE ri.order_item_id=? AND r.status<>'rejected'");$already->execute([$it['id']]);$remaining=(float)$it['quantity']-(float)$already->fetchColumn();if($qty>$remaining+0.000001)throw new RuntimeException('İade miktarı siparişte kalan iade edilebilir miktarı aşamaz.');$refund=round(((float)$it['line_total']/(float)$it['quantity'])*$qty,2);$items[]=['item'=>$it,'qty'=>$qty,'refund'=>$refund];$total+=$refund;}
     if(!$items)throw new RuntimeException('İade edilecek en az bir ürün miktarı girin.');
     $db->beginTransaction();$tmp='TMP-'.bin2hex(random_bytes(8));$q=$db->prepare("INSERT INTO sales_returns (return_number,order_id,customer_id,status,reason,notes,refund_total,created_by,created_at) VALUES (?,?,?,'requested',?,?,?,?,NOW())");$q->execute([$tmp,$orderId,$order['customer_id'],$reason,trim((string)($_POST['notes']??''))?:null,$total,(int)$admin['id']]);$returnId=(int)$db->lastInsertId();$number='IADE-'.date('Y').'-'.str_pad((string)$returnId,6,'0',STR_PAD_LEFT);$db->prepare('UPDATE sales_returns SET return_number=? WHERE id=?')->execute([$number,$returnId]);$ins=$db->prepare('INSERT INTO sales_return_items (return_id,order_item_id,product_id,product_name,quantity,refund_amount,created_at) VALUES (?,?,?,?,?,?,NOW())');foreach($items as $entry){$it=$entry['item'];$ins->execute([$returnId,$it['id'],$it['product_id'],$it['product_name'],$entry['qty'],$entry['refund']]);}$db->prepare('INSERT INTO sales_return_events (return_id,from_status,to_status,note,user_id,created_at) VALUES (?,NULL,?,?,?,NOW())')->execute([$returnId,'requested','İade talebi oluşturuldu',(int)$admin['id']]);$db->commit();kd_audit('return.created','sales_return',$returnId);\KodVadAll\Core\NotificationService::notifyRoles($db,['owner','admin','manager'],'Yeni iade talebi','Yeni bir satış iade talebi oluşturuldu.','index.php?page=returns&action=view&id='.$returnId,'warning');\KodVadAll\Core\WebhookService::enqueue($db,'return.created',['id'=>$returnId,'order_id'=>$orderId]);
     self::go('view',$returnId);
    }
    if($form==='status'){
     $returnId=(int)($_POST['return_id']??0);$to=(string)($_POST['status']??'');$note=trim((string)($_POST['note']??''));$allowed=['requested'=>['approved','rejected'],'approved'=>['received'],'received'=>['closed'],'refunded'=>['closed'],'rejected'=>['closed'],'closed'=>[]];
     $db->beginTransaction();$defaultWarehouseId=(int)$db->query("SELECT id FROM warehouses WHERE is_default=1 AND status='active' LIMIT 1")->fetchColumn();if($defaultWarehouseId<1)throw new RuntimeException('Varsayılan depo bulunamadı.');$q=$db->prepare('SELECT * FROM sales_returns WHERE id=? FOR UPDATE');$q->execute([$returnId]);$r=$q->fetch();if(!$r)throw new RuntimeException('İade kaydı bulunamadı.');$from=$r['status'];if(!in_array($to,$allowed[$from]??[],true))throw new RuntimeException('Bu iade durum geçişine izin verilmiyor.');
     if($to==='received'){
      $restock=is_array($_POST['restock_qty']??null)?$_POST['restock_qty']:[];$q=$db->prepare('SELECT * FROM sales_return_items WHERE return_id=? ORDER BY id FOR UPDATE');$q->execute([$returnId]);$items=$q->fetchAll();
      foreach($items as $it){$qty=(float)($restock[$it['id']]??0);if($qty<0||$qty>(float)$it['quantity']+0.000001)throw new RuntimeException('Stoka alınacak miktar iade miktarını aşamaz.');$db->prepare('UPDATE sales_return_items SET restock_quantity=? WHERE id=?')->execute([$qty,$it['id']]);$pid=(int)($it['product_id']??0);if($pid>0&&$qty>0){$q=$db->prepare('SELECT stock_quantity,track_stock FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$p=$q->fetch();if($p&&(int)$p['track_stock']){$ws=$db->prepare('SELECT quantity FROM product_warehouse_stocks WHERE product_id=? AND warehouse_id=? FOR UPDATE');$ws->execute([$pid,$defaultWarehouseId]);$stock=$ws->fetch();$before=$stock?(float)$stock['quantity']:0.0;$after=$before+$qty;if(!$stock)$db->prepare('INSERT INTO product_warehouse_stocks(product_id,warehouse_id,quantity,updated_at) VALUES(?,?,?,NOW())')->execute([$pid,$defaultWarehouseId,$after]);else $db->prepare('UPDATE product_warehouse_stocks SET quantity=?,updated_at=NOW() WHERE product_id=? AND warehouse_id=?')->execute([$after,$pid,$defaultWarehouseId]);$total=(float)$db->query('SELECT COALESCE(SUM(quantity),0) FROM product_warehouse_stocks WHERE product_id='.$pid)->fetchColumn();$db->prepare('UPDATE products SET stock_quantity=?,updated_at=NOW() WHERE id=?')->execute([$total,$pid]);$db->prepare("INSERT INTO product_stock_movements(product_id,warehouse_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,reference_type,reference_id,created_at) VALUES(?,?,?,'in',?,?,?,?,?,?,NOW())")->execute([$pid,$defaultWarehouseId,(int)$admin['id'],$qty,$before,$after,'Müşteri iadesi '.$r['return_number'],'return',$returnId]);}}}
      $db->prepare('UPDATE sales_returns SET received_at=NOW() WHERE id=?')->execute([$returnId]);
     }
     $db->prepare('UPDATE sales_returns SET status=?,reviewed_by=?,updated_at=NOW() WHERE id=?')->execute([$to,(int)$admin['id'],$returnId]);$db->prepare('INSERT INTO sales_return_events (return_id,from_status,to_status,note,user_id,created_at) VALUES (?,?,?,?,?,NOW())')->execute([$returnId,$from,$to,$note?:null,(int)$admin['id']]);$db->commit();kd_audit('return.status_changed','sales_return',$returnId);self::go('view',$returnId);
    }
    if($form==='refund'){
     $returnId=(int)($_POST['return_id']??0);$accountId=(int)($_POST['account_id']??0);$amount=(float)($_POST['amount']??0);$db->beginTransaction();$q=$db->prepare('SELECT r.*,o.currency FROM sales_returns r JOIN orders o ON o.id=r.order_id WHERE r.id=? FOR UPDATE');$q->execute([$returnId]);$r=$q->fetch();if(!$r||!in_array($r['status'],['received','refunded'],true))throw new RuntimeException('Ödeme için ürün teslim alınmış iade kaydı gereklidir.');$remaining=(float)$r['refund_total']-(float)$r['refunded_total'];if($amount<=0||$amount>$remaining+0.000001)throw new RuntimeException('Ödeme tutarı kalan iade tutarını aşamaz.');$q=$db->prepare("SELECT id,currency FROM financial_accounts WHERE id=? AND status='active'");$q->execute([$accountId]);$account=$q->fetch();if(!$account||$account['currency']!==$r['currency'])throw new RuntimeException('Sipariş ile aynı para biriminde aktif hesap seçin.');$db->prepare("INSERT INTO financial_transactions (account_id,transaction_type,direction,amount,currency,transaction_date,party_type,party_id,category,reference_no,description,created_by,created_at) VALUES (?,'expense','debit',?,?,CURDATE(),'customer',?,'Müşteri iadesi',?,?,?,NOW())")->execute([$accountId,$amount,$r['currency'],$r['customer_id'],$r['return_number'],'İade ödemesi '.$r['return_number'],(int)$admin['id']]);$newPaid=(float)$r['refunded_total']+$amount;$status=$newPaid+0.000001>=(float)$r['refund_total']?'refunded':'received';$db->prepare('UPDATE sales_returns SET refunded_total=?,status=?,refunded_at=IF(?="refunded",NOW(),refunded_at),updated_at=NOW() WHERE id=?')->execute([$newPaid,$status,$status,$returnId]);$db->prepare('INSERT INTO sales_return_events (return_id,from_status,to_status,note,user_id,created_at) VALUES (?,?,?,?,?,NOW())')->execute([$returnId,$r['status'],$status,'İade ödemesi: '.number_format($amount,2,'.',' '),(int)$admin['id']]);$db->commit();kd_audit('return.refund_recorded','sales_return',$returnId);self::go('view',$returnId);
    }
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('KodVadAll returns: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'İade işlemi tamamlanamadı.';$action=(string)($_GET['action']??'list');$id=max(0,(int)($_GET['id']??0));}
  }
  if($action==='create'){$orderId=max(0,(int)($_GET['order_id']??0));if($orderId>0){$q=$db->prepare("SELECT * FROM orders WHERE id=? AND status IN ('shipped','completed')");$q->execute([$orderId]);$order=$q->fetch();if(!$order)self::notFound();$q=$db->prepare('SELECT oi.*,(oi.quantity-COALESCE((SELECT SUM(ri.quantity) FROM sales_return_items ri JOIN sales_returns sr ON sr.id=ri.return_id WHERE ri.order_item_id=oi.id AND sr.status<>\'rejected\'),0)) returnable FROM order_items oi WHERE oi.order_id=? AND oi.product_id IS NOT NULL ORDER BY oi.id');$q->execute([$orderId]);$orderItems=$q->fetchAll();}else{$orders=$db->query("SELECT o.id,o.order_number,c.name customer_name,o.created_at FROM orders o LEFT JOIN customers c ON c.id=o.customer_id WHERE o.status IN ('shipped','completed') ORDER BY o.id DESC LIMIT 200")->fetchAll();}}
  elseif($action==='view'){$q=$db->prepare('SELECT r.*,o.order_number,o.currency,c.name customer_name FROM sales_returns r JOIN orders o ON o.id=r.order_id LEFT JOIN customers c ON c.id=r.customer_id WHERE r.id=?');$q->execute([$id]);$record=$q->fetch();if(!$record)self::notFound();$q=$db->prepare('SELECT * FROM sales_return_items WHERE return_id=? ORDER BY id');$q->execute([$id]);$items=$q->fetchAll();$q=$db->prepare('SELECT e.*,u.name user_name FROM sales_return_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.return_id=? ORDER BY e.id DESC');$q->execute([$id]);$events=$q->fetchAll();$accounts=$db->prepare("SELECT id,name,currency FROM financial_accounts WHERE status='active' AND currency=? ORDER BY name");$accounts->execute([$record['currency']]);$refundAccounts=$accounts->fetchAll();}
  else{$status=in_array($_GET['status']??'',array_keys(self::LABELS),true)?$_GET['status']:'';$q=trim((string)($_GET['q']??''));$where=[];$params=[];if($q!==''){$where[]='(r.return_number LIKE ? OR o.order_number LIKE ? OR c.name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($status!==''){$where[]='r.status=?';$params[]=$status;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$st=$db->prepare('SELECT r.*,o.order_number,o.currency,c.name customer_name FROM sales_returns r JOIN orders o ON o.id=r.order_id LEFT JOIN customers c ON c.id=r.customer_id'.$sql.' ORDER BY r.id DESC LIMIT 150');$st->execute($params);$returns=$st->fetchAll();}
  $pageTitle='İade & Değişim';ob_start();require KD_ROOT.'/app/Views/returns/index.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
 private static function go(string $action='list',int $id=0):never{$u='index.php?page=returns';if($action!=='list')$u.='&action='.$action;if($id)$u.='&id='.$id;header('Location: '.$u,true,303);exit;}
 private static function notFound():never{http_response_code(404);exit('İade kaydı bulunamadı.');}
}
